window.RESOURCE_BANK_DATA = {"resources":[{"id":"fit-admin-corrections","title":"Correcting administrative fitness assessment errors","question":"Can my fitness assessment score be corrected if myFitness is wrong?","category":"Fitness","source":"AFMAN 36-2905","sourceDate":"24 Mar 2026","authority":"Official DAF","paragraph":"8.4","page":"55","answer":"Administrative corrections are limited to specified errors such as a mismatch between repetitions performed and repetitions entered in myFitness, profile-date or exemption updates, duplicate score entries, and an assessment taken while pregnant. The FAC submits administrative correction requests to the servicing Fitness Information Manager.","keywords":["fitness","myfitness","score correction","administrative error","repetitions","profile","exemption","pregnant"],"document":"documents/dafman36-2905.pdf"},{"id":"fit-first-duty-station","title":"First official PFRA after arriving at first duty station","question":"When is a new Airman's first official fitness assessment due?","category":"Fitness","source":"AFMAN 36-2905","sourceDate":"24 Mar 2026","authority":"Official DAF","paragraph":"6.1.1","page":"47","answer":"A member's first PFRA is due at the next unit-scheduled PFRA or within two months after arrival at the first duty station. For new accessions, assessments administered before the first duty station are not considered the first official PFRA for myFitness purposes.","keywords":["first pt test","new airman","first duty station","pfra","fitness due"],"document":"documents/dafman36-2905.pdf"},{"id":"fit-frp-tdys","title":"Fitness Reconditioning Program and long TDYs","question":"What happens if an Airman in a fitness intervention program goes TDY for more than six weeks?","category":"Fitness","source":"AFMAN 36-2905","sourceDate":"24 Mar 2026","authority":"Official DAF","paragraph":"5.6.9","page":"46","answer":"For a training TDY longer than six weeks, the commander must send the gaining commander or equivalent a memorandum describing the required intervention, follow-up, and assessment at least two weeks before the TDY. ARC handling is at commander discretion.","keywords":["frp","fitness reconditioning","tdy","six weeks","intervention","commander"],"document":"documents/dafman36-2905.pdf"},{"id":"safety-supervisor","title":"Supervisor safety responsibilities","question":"What are my responsibilities as a supervisor for workplace safety?","category":"Safety & Risk Management","source":"DAFMAN 91-203","sourceDate":"24 Feb 2026","authority":"Official DAF","paragraph":"1.2.5","page":"16","answer":"Supervisors must ensure employees are trained before operating equipment or performing assigned tasks, routinely evaluate safe equipment/PPE use, correct unsafe behavior on the spot, provide initial and refresher instruction, and use a job hazard analysis when guidance is not available. Higher-risk or new tasks require pre-task safety briefings.","keywords":["supervisor","safety responsibilities","pre-task brief","jha","ppe","training"],"document":"documents/dafman91-203.pdf"},{"id":"safety-rings","title":"Ring and jewelry restrictions in industrial work","question":"Can I wear a ring while doing materials handling or working around equipment?","category":"Safety & Risk Management","source":"DAFMAN 91-203","sourceDate":"24 Feb 2026","authority":"Official DAF","paragraph":"2.3.1","page":"21","answer":"Personnel engaged in industrial work, including materials handling, aircraft/vehicle/equipment maintenance, climbing, or work around moving machinery, will not wear rings. The manual also restricts conductive or snag hazards in several related situations.","keywords":["rings","jewelry","materials handling","warehouse","industrial","maintenance"],"document":"documents/dafman91-203.pdf"},{"id":"safety-lightning","title":"Lightning Warning actions","question":"What do we do when a Lightning Warning is issued?","category":"Safety & Risk Management","source":"DAFMAN 91-203","sourceDate":"24 Feb 2026","authority":"Official DAF","paragraph":"3.2.2","page":"33","answer":"A Lightning Warning is in effect when lightning occurs within five nautical miles of the predetermined location or activity. Personnel in affected locations or activities must stop outside activity and seek shelter until the supporting weather organization cancels the warning.","keywords":["lightning","weather","five nautical miles","flightline","stop operations"],"document":"documents/dafman91-203.pdf"},{"id":"safety-fire-extinguisher","title":"Monthly fire extinguisher inspection","question":"How often do fire extinguishers have to be visually inspected?","category":"Safety & Risk Management","source":"DAFMAN 91-203","sourceDate":"24 Feb 2026","authority":"Official DAF","paragraph":"6.2.6.8","page":"43-44","answer":"Managers and supervisors must ensure a visual inspection is performed and documented monthly for all fire extinguishers under their control. Discrepant extinguishers are removed from service and replaced immediately until repaired.","keywords":["fire extinguisher","monthly inspection","fire safety","supervisor"],"document":"documents/dafman91-203.pdf"},{"id":"safety-extension-cords","title":"Extension cord and power strip rules","question":"Can I daisy-chain power strips or extension cords?","category":"Safety & Risk Management","source":"DAFMAN 91-203","sourceDate":"24 Feb 2026","authority":"Official DAF","paragraph":"8.2.1 / 8.4","page":"63-64","answer":"No. Multiple plug adapters or strips may not be connected to another multiple plug adapter or strip. Extension cords must be used only within the applicable electrical safety rules and defective cords must be removed from service.","keywords":["power strip","extension cord","daisy chain","electrical safety"],"document":"documents/dafman91-203.pdf"},{"id":"v2-seat-release","title":"ATOC passenger seat release timing","question":"When does ATOC have to give Passenger Service a firm seat release?","category":"2T2 / Aerial Port","subCategory":"Passenger Service / ATOC","source":"DAFI 24-605V2","sourceDate":"30 Jan 2025 + 4 Feb 2026 DAFGM","authority":"Official DAF","paragraph":"2.12.3","page":"20-21","answer":"ATOC provides a firm seat release to the passenger terminal no later than five hours before mission departure, or as soon as requirements are known. For missions with flight times of two hours or less, every effort is made to determine the release as early as possible.","keywords":["seat release","atoc","passenger service","five hours","mission departure"],"document":"documents/dafi24-605v2.pdf"},{"id":"v2-space-a-rollcall","title":"Space-A roll call selection","question":"How are Space-A passengers selected during roll call?","category":"2T2 / Aerial Port","subCategory":"Passenger Service","source":"DAFI 24-605V2","sourceDate":"30 Jan 2025 + 4 Feb 2026 DAFGM","authority":"Official DAF","paragraph":"2.34","page":"27","answer":"Space-A roll call begins the selection process. Eligible passengers are selected by category and then by date/time of sign-up. Passengers must be marked present and travel ready at the start of roll call, with required documentation, baggage, and accompanying family members present.","keywords":["space a","roll call","passenger","category","date time sign-up","travel ready"],"document":"documents/dafi24-605v2.pdf"},{"id":"v2-unruly-passenger","title":"Handling an unruly passenger","question":"Who can deny boarding to an unruly passenger?","category":"2T2 / Aerial Port","subCategory":"Passenger Service","source":"DAFI 24-605V2","sourceDate":"30 Jan 2025 + 4 Feb 2026 DAFGM","authority":"Official DAF","paragraph":"2.9-2.10","page":"19","answer":"Supervisors use judgment on when to deny boarding, transportation, or contact law enforcement for unruly or violent behavior. The decision to deny boarding is made by the shift supervisor, with elevation as high as the installation commander depending on circumstances and rank. Once aboard, aircrew or troop commander authority applies for safety.","keywords":["unruly passenger","deny boarding","shift supervisor","law enforcement"],"document":"documents/dafi24-605v2.pdf"},{"id":"v2-ltc-safety","title":"Load Team Chief safety brief","question":"What does the Load Team Chief have to brief before loading operations?","category":"2T2 / Aerial Port","subCategory":"Ramp / Aircraft Services","source":"DAFI 24-605V2 DAFGM 2026-01","sourceDate":"4 Feb 2026","authority":"Official DAF - Guidance Memorandum","paragraph":"Table A8.1","page":"3","answer":"Before load-team operations, the Load Team Chief briefs applicable weather, PPE and jewelry removal, personnel roles and upload/download requirements, positive cargo control, spotting restrictions, immediate correction of unsafe operations, danger zones, fall hazards, and emergency evacuation routes/rally points. Additional explosive safety items apply when applicable.","keywords":["load team chief","ltc","safety brief","ramp","load team","explosive"],"document":"documents/dafi24-605v2.pdf"},{"id":"v2-ltc-checklist","title":"Load Team Chief checklist","question":"What should a Load Team Chief check before aircraft loading?","category":"2T2 / Aerial Port","subCategory":"Ramp / Aircraft Services","source":"DAFI 24-605V2 DAFGM 2026-01","sourceDate":"4 Feb 2026","authority":"Official DAF - Guidance Memorandum","paragraph":"Table A8.3","page":"5-6","answer":"The LTC checklist includes reviewing the sequence of events, load setup and inspection, assigning crew duties, verifying qualifications, ensuring required loading equipment is available, reviewing ATTLA requirements when applicable, conducting a mission-tailored safety brief with the aircrew representative, verifying PPE, and maintaining positive cargo control throughout on/offload operations.","keywords":["load team chief","checklist","attla","crew duties","positive control","loading"],"document":"documents/dafi24-605v2.pdf"},{"id":"v5-ltc-qual","title":"Load Team Chief qualification requirements","question":"What do I need to become a Load Team Chief?","category":"2T2 / Aerial Port","subCategory":"Training / Ramp","source":"DAFI 24-605V5 DAFGM 2026-01","sourceDate":"30 Jan 2026","authority":"Official DAF - Guidance Memorandum","paragraph":"2.14.2","page":"2-3","answer":"The updated LTC requirements include at least six months as a Load Team member; completion of local ramp and aircraft-services master task-list requirements; MHE familiarization applicable to the location; hazardous material handler qualification; required General Hazards/Accident-Mishap Prevention and ramp TTGs; demonstrated competence on multiple aircraft types under supervision; and an AF Form 483 or installation equivalent for flightline driving.","keywords":["ltc","load team chief","six months","hazmat handler","af form 483","ramp training"],"document":"documents/dafi24-605v5.pdf"},{"id":"v5-training-doc","title":"Air Transportation training documentation","question":"Where should 2T2 training be documented?","category":"Training & Development","subCategory":"2T2 Training","source":"DAFI 24-605V5","sourceDate":"3 Sep 2025 + 30 Jan 2026 DAFGM","authority":"Official DAF","paragraph":"2.8","page":"11","answer":"Training must be verified using ADLS/MyLearning certificates or official training transcripts. Initial training and refresher evaluations are documented in MyTraining, G081, or an approved equivalent system/database for military and civilian employees. Training folders are established for personnel without OJT records.","keywords":["training documentation","g081","mytraining","mylearning","ojt","2t2"],"document":"documents/dafi24-605v5.pdf"},{"id":"v5-pa-60-days","title":"Proficiency assessment after duty station or position change","question":"How long do I have to complete a proficiency assessment after changing duty station or duty position?","category":"Training & Development","subCategory":"2T2 Training","source":"DAFI 24-605V5","sourceDate":"3 Sep 2025 + 30 Jan 2026 DAFGM","authority":"Official DAF","paragraph":"2.6","page":"11","answer":"A qualified trainer must complete a proficiency assessment when an individual changes duty station, changes duty position, or when tasks are unarchived in training records. The assessment must be completed within 60 calendar days and documented in the trainee's training record.","keywords":["proficiency assessment","pa","60 days","duty station","duty position","unarchived"],"document":"documents/dafi24-605v5.pdf"},{"id":"v5-kloader-pa","title":"K-Loader proficiency and recertification","question":"How often do K-Loader operators need proficiency assessments?","category":"2T2 / Aerial Port","subCategory":"MHE / K-Loader","source":"DAFI 24-605V5","sourceDate":"3 Sep 2025 + 30 Jan 2026 DAFGM","authority":"Official DAF","paragraph":"2.11.7 / 2.12","page":"15-16","answer":"The instruction requires a biannual proficiency assessment for all 25K/60K operators. MHE operators also undergo recertification in accordance with AFMAN 24-306; the instruction notes three-year recertification for applicable MHE and certain staircase trucks.","keywords":["k-loader","25k","60k","halvorsen","tunner","proficiency assessment","recertification"],"document":"documents/dafi24-605v5.pdf"},{"id":"v5-loadplanning","title":"Initial Load Planning qualification","question":"What do I need to become load-planning qualified?","category":"2T2 / Aerial Port","subCategory":"Load Planning","source":"DAFI 24-605V5","sourceDate":"3 Sep 2025 + 30 Jan 2026 DAFGM","authority":"Official DAF","paragraph":"2.21.2","page":"19","answer":"Initial load-planning trainees complete applicable TTG lessons, possess a 5-skill level or civilian equivalent, complete Load Planning I (Basic) and applicable Load Planning II airframe-specific courses, understand aircraft characteristics and ATTLA requirements, continue OJT until proficient, and know hazardous-material compatibility processes.","keywords":["load planning","qualification","5 skill level","load planning 1","load planning ii","attla"],"document":"documents/dafi24-605v5.pdf"},{"id":"v5-ji","title":"Joint Inspector initial qualification","question":"What are the requirements to become a Joint Inspector?","category":"2T2 / Aerial Port","subCategory":"Joint Inspection","source":"DAFI 24-605V5","sourceDate":"3 Sep 2025 + 30 Jan 2026 DAFGM","authority":"Official DAF","paragraph":"2.24.7","page":"22-23","answer":"Joint inspectors must hold at least the awarded 5-skill level or civilian equivalent, demonstrate strong cargo and ramp proficiency, maintain HAZMAT inspector or preparer qualification, complete specified distance-learning courses and the JI TTG/unit course, and complete at least two successful JIs under a qualified JI trainer. Annual and biennial proficiency/refresher requirements also apply.","keywords":["joint inspector","ji","5 skill level","hazmat inspector","two successful ji","refresher"],"document":"documents/dafi24-605v5.pdf"},{"id":"v5-atsep-nogo","title":"ATSEP Performance Evaluation No-Go follow-up","question":"What happens after an ATSEP Performance Evaluation No-Go?","category":"Training & Development","subCategory":"ATSEP","source":"DAFI 24-605V5","sourceDate":"3 Sep 2025 + 30 Jan 2026 DAFGM","authority":"Official DAF","paragraph":"4.6.16 / 4.7.9 / 4.9.1","page":"32-33","answer":"A No-Go requires notification to the member's flight/section leadership within one duty day, remedial training, and re-evaluation no earlier than 24 hours and no later than 30 days after the No-Go. Section leadership develops the remediation plan, and repeated No-Go results on the same CFETP STS line item can lead to decertification.","keywords":["atsep","no-go","remedial training","24 hours","30 days","decertify"],"document":"documents/dafi24-605v5.pdf"},{"id":"604-applicability","title":"What AFMAN 24-604 covers","question":"What does AFMAN 24-604 apply to?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"1.1","page":"6","answer":"AFMAN 24-604 provides procedures for preparing hazardous materials for shipment by military aircraft, including packaging, marking, labeling, passenger movement with hazardous materials, and notification to the aircraft commander. Personnel whose duties include these functions must comply with the manual.","keywords":["afman 24-604","hazmat","hazardous materials","applicability","military air shipment"],"document":"documents/afman24-604.pdf"},{"id":"604-roles","title":"HAZMAT worker roles and responsibilities","question":"What is the difference between a HAZMAT handler, preparer, inspector, and load planner?","category":"Training & Development","subCategory":"Hazardous Materials","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"1.2.9-1.2.13","page":"9","answer":"Packers package hazardous materials but do not sign legally binding documents. Preparers certify classification, description, packaging, marking, labeling, and airlift condition. Handlers maintain safe operations and job-specific proficiency while routinely handling hazardous materials. Inspectors verify proper preparation and documentation before entry into military airlift. Movement planners, including load planners, ensure hazardous materials and passengers are planned within required limitations, separation, and accessibility.","keywords":["handler","preparer","inspector","movement planner","load planner","hazmat roles","packer"],"document":"documents/afman24-604.pdf"},{"id":"604-training","title":"HAZMAT training requirements","question":"What training does a hazardous material worker need?","category":"Training & Development","subCategory":"Hazardous Materials","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"1.3","page":"9","answer":"Commanders assign hazardous material workers and ensure relevant training is completed in accordance with Attachment 25. At a minimum, training covers general awareness/familiarization, safety and emergency response, function-specific responsibilities, and security awareness.","keywords":["hazmat training","attachment 25","general awareness","security awareness","emergency response","handler training"],"document":"documents/afman24-604.pdf"},{"id":"604-damaged","title":"Damaged or leaking HAZMAT shipment","question":"What do I do with damaged or leaking hazardous cargo?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"1.7","page":"10-11","answer":"Do not transport a shipment that is damaged, leaking, or improperly packed, marked, or labeled. Remove cargo that appears to be leaking or contaminated and inspect adjacent cargo and the stowage area for contamination. Local installation emergency-response procedures apply. Dropped or damaged explosives must not be moved; EOD or UXO-qualified personnel determine disposition.","keywords":["leaking hazmat","damaged shipment","frustrate","spill","contaminated cargo","eod","dropped explosive"],"document":"documents/afman24-604.pdf"},{"id":"604-mre","title":"HAZMAT and MRE pallet compatibility","question":"Can hazardous materials be loaded on the same 463L pallet as MREs or food?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials / Pallet Build-up","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"1.8.4","page":"11","answer":"Liquid or toxic hazardous materials are not stowed on the same aircraft pallet with food, feed, or other edible material. If operational necessity requires other hazardous material with food or MREs, the manual imposes additional conditions, including no hazardous liquid or Division 2.3 gas with the food, separation by the greatest possible distance but at least 44 inches for applicable hazardous material, and no hazardous material above the food/MREs.","keywords":["mre","food","463l pallet","hazmat compatibility","44 inches","pallet build-up"],"document":"documents/afman24-604.pdf"},{"id":"604-accessibility","title":"In-flight accessibility of hazardous materials","question":"Does hazardous cargo have to be accessible in flight?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials / Load Planning","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"1.11","page":"13","answer":"Yes, hazardous materials generally must be positioned so aircrew have visual and physical access during flight. Hazardous material should not be shipped in freight containers that are not easily accessible, except for specifically authorized items. Joint inspectors also require knowledge of and access to transportation containers containing hazardous materials.","keywords":["accessibility","in flight","hazmat access","container","load planning","joint inspection"],"document":"documents/afman24-604.pdf"},{"id":"604-brief-aircraft-commander","title":"Aircraft commander HAZMAT notification","question":"Who has to notify the aircraft commander about hazardous material?","category":"2T2 / Aerial Port","subCategory":"ATOC / Special Handling","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"1.2.8","page":"9","answer":"Air terminal or base operations personnel notify the aircraft commander, or designated representative, in writing of all hazardous materials aboard the aircraft. If there is no established air terminal or base operations function, the activity delivering the cargo to the aircraft provides the notification. Attachment 21 contains briefing-agency requirements.","keywords":["aircraft commander","hazmat brief","briefing agency","notification","special handling"],"document":"documents/afman24-604.pdf"},{"id":"604-hidden","title":"Hidden hazardous shipment indicators","question":"What cargo should make me suspect hidden hazardous materials?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials / Inspection","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"A3.1.17 / Table A3.2","page":"59-61","answer":"Personnel should suspect hidden hazards in cargo such as aircraft parts, deployment equipment, electrical equipment, generators, engines, ground support equipment, individual equipment, medical supplies, repair kits, survival kits, toolboxes, UPS units, vehicles, and vessel parts. If a hazard is suspected, the shipment is frustrated and coordinated with the shipping activity for resolution.","keywords":["hidden hazard","undeclared hazmat","toolbox","generator","vehicle","battery","deployment equipment","frustrate shipment"],"document":"documents/afman24-604.pdf"},{"id":"604-empty-cylinder","title":"When a compressed gas cylinder is considered empty","question":"When is a compressed gas cylinder considered empty for air shipment?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials / Class 2","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"A3.1.16.2","page":"58-59","answer":"A compressed gas cylinder is considered empty when its pressure is less than 40 psia at 21°C (70°F), subject to additional requirements. Cylinders containing residue of certain hazardous gases remain regulated as full unless completely cleaned and purged.","keywords":["empty cylinder","40 psia","compressed gas","class 2","residue"],"document":"documents/afman24-604.pdf"},{"id":"604-ten-steps","title":"10 steps for preparing hazardous material","question":"What are the steps for preparing hazardous material for military air shipment?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"Attachment 2, Table A2.1","page":"50-52","answer":"Attachment 2 presents a 10-step workflow: verify training; identify the material; determine the proper shipping name and hazardous-material description; determine Chapter 3/non-Chapter 3 requirements; package the item; verify packaging acceptability; mark and label the package; complete hazardous-material certification; verify compatibility; and complete briefing-agency requirements.","keywords":["10 steps","prepare hazardous material","psn","packaging","label","marking","certification","compatibility","briefing"],"document":"documents/afman24-604.pdf"},{"id":"604-waiver","title":"Packaging and compatibility waiver basics","question":"When is a HAZMAT waiver required?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials / Waivers","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"2.3","page":"16-18","answer":"A packaging waiver is required for a hazardous item or packaging not authorized by Attachments 5 through 13. A compatibility waiver is required when hazardous materials that are incompatible under Attachment 18 must move on the same military aircraft, unless an exception applies. Safety and risk management are the overriding factors; convenience is not a basis for a waiver.","keywords":["hazmat waiver","packaging waiver","compatibility waiver","incompatible","chapter 2"],"document":"documents/afman24-604.pdf"},{"id":"604-certification","title":"Shipper's hazardous material certification","question":"Is a Shipper's Declaration required for hazardous material?","category":"2T2 / Aerial Port","subCategory":"Hazardous Materials / Certification","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"A17.1","page":"445","answer":"Unless specifically exempted by AFMAN 24-604, the shipping activity must complete a shipper's certification for military air shipments of hazardous materials in accordance with Attachment 17.","keywords":["shipper declaration","certification","dangerous goods","attachment 17","hazmat paperwork"],"document":"documents/afman24-604.pdf"},{"id":"604-passenger-cargo-compartment","title":"HAZMAT location on contracted passenger aircraft","question":"Can hazardous material be carried in the passenger compartment?","category":"2T2 / Aerial Port","subCategory":"Passenger Service / Hazardous Materials","source":"AFMAN 24-604","sourceDate":"6 Jun 2025","authority":"Official DAF / Joint-Service","paragraph":"A23.3.2.4 / A23.4","page":"498","answer":"For the contracted passenger-aircraft provisions cited in Attachment 23, hazardous materials are loaded only in the cargo compartment and are not authorized in the passenger compartment. Separate requirements apply depending on the aircraft and authority being used.","keywords":["passenger compartment","hazmat passenger aircraft","cargo compartment","contract air carrier"],"document":"documents/afman24-604.pdf"}],"categories":[{"name":"Supervision & Leadership","icon":"👥"},{"name":"Evaluations & Promotions","icon":"📊"},{"name":"Training & Development","icon":"🎓"},{"name":"Fitness","icon":"🏃"},{"name":"Leave & Duty Status","icon":"📅"},{"name":"Pay & Benefits","icon":"💵"},{"name":"PCS / TDY / Deployments","icon":"🧳"},{"name":"Awards & Decorations","icon":"🏅"},{"name":"Standards & Discipline","icon":"⚖️"},{"name":"Career Management","icon":"✈️"},{"name":"Airman & Family Resources","icon":"👨‍👩‍👧"},{"name":"Safety & Risk Management","icon":"🛡️"},{"name":"DAF Publications","icon":"📘"},{"name":"Local Policies","icon":"🏢"},{"name":"Hazardous Materials","icon":"☣️"},{"name":"2T2 / Aerial Port","icon":"🛫"},{"name":"Who Do I Contact?","icon":"☎️"},{"name":"C-17 Loading & Load Planning","icon":"🛩️"}],"toolkit":[{"label":"New Airman","icon":"👥","query":"first official PFRA new Airman training"},{"label":"Performance","icon":"📈","query":"proficiency assessment supervisor"},{"label":"PT Failure","icon":"🏃","query":"fitness"},{"label":"EPB / EPR","icon":"📄","query":"EPB"},{"label":"PCS / TDY","icon":"✈️","query":"TDY"},{"label":"Awards","icon":"🏅","query":"awards"},{"label":"Load Team Chief","icon":"🦺","query":"Load Team Chief"},{"label":"Joint Inspection","icon":"✅","query":"Joint Inspector"},{"label":"K-Loader","icon":"🚜","query":"K-Loader"},{"label":"Safety","icon":"🛡️","query":"supervisor safety"},{"label":"HAZMAT","icon":"☣️","query":"hazardous materials"},{"label":"C-17 Load Planning","icon":"🛩️","query":"C-17 load planning"}],"updates":[{"title":"TO 1C-17A-9","meta":"1 Jul 2024 • C-17A Loading Instructions • Distribution D / export restricted","type":"Restricted Technical Order"},{"title":"AFMAN 24-604","meta":"6 Jun 2025 • Preparing Hazardous Materials for Military Air Shipments","type":"Official DAF / Joint-Service"},{"title":"DAFI 24-605V2 DAFGM 2026-01","meta":"4 Feb 2026 • Load Team Chief checklist and passenger routing updates","type":"Official DAF"},{"title":"DAFI 24-605V5 DAFGM 2026-01","meta":"30 Jan 2026 • Updated Load Team Chief program and qualification tracking","type":"Official DAF"},{"title":"AFMAN 36-2905","meta":"24 Mar 2026 • Physical Fitness Readiness Program","type":"Official DAF"},{"title":"DAFMAN 91-203","meta":"24 Feb 2026 • Occupational Safety, Fire, and Health Standards","type":"Official DAF"},{"title":"CFETP 2T2X1","meta":"Air Transportation career-field training source","type":"Official DAF"}]};
